{"code":"# Re-checking the 'F-A-U-L-T' status for other models.
# The payload looks like this for some entries (with 'state' instead of 'status'):
# {'fw': '2.9.0', 'data': {...}, 'state': {'code': 'FAULT'}}
def get_status_improved(payload_str):
    import json
    try:
        data = json.loads(payload_str)
        # Check 'status' key
        status = data.get('status')
        if status:
            return str(status).lower()
        # Check 'state': {'code': '...'} structure
        state = data.get('state')
        if isinstance(state, dict):
            code = state.get('code')
            if code:
                return str(code).lower()
    except (json.JSONDecodeError, TypeError):
        return None
    return None

# Apply to all readings to see if we find more 'fault'
readings_df = dfs[1]
statuses = readings_df['payload'].apply(get_status_improved)
print(f"Unique statuses found: {statuses.unique()}")
print(f"Faults found: {len(statuses[statuses == 'fault'])}")

# Now filter by date and device_id too
tx200_devices = dfs[0][dfs[0]['model'] == 'TX-200']['device_id'].unique()
readings_filtered = readings_df[readings_df['recorded_at'].str.startswith('2025-07')].copy()
readings_filtered = readings_filtered[readings_filtered['device_id'].isin(tx200_devices)].copy()

readings_filtered['status'] = readings_filtered['payload'].apply(get_status_improved)
fault_readings = readings_filtered[readings_filtered['status'] == 'fault']
print(f"Fault readings for TX-200 in July 2025: {len(fault_readings)}")
